package com.xyz.question_bank_management_system.modules.agent.mapper;
import com.xyz.question_bank_management_system.modules.agent.entity.*;
import com.xyz.question_bank_management_system.modules.agent.entity.ResourceBundle;
import com.xyz.question_bank_management_system.modules.learning.entity.*;
import org.apache.ibatis.annotations.*;
import java.util.*;
@Mapper public interface PersonalizedResourceMapper {
 @Insert("INSERT INTO resource_unit(resource_unit_code,course_id,path_id,path_version_id,status,aggregation_evidence_json,correlation_id,created_at) VALUES(#{resourceUnitCode},#{courseId},#{pathId},#{pathVersionId},#{status},#{aggregationEvidenceJson},#{correlationId},NOW(3))") @Options(useGeneratedKeys=true,keyProperty="id") int insertUnit(ResourceUnit v);
 @Select("SELECT * FROM resource_unit WHERE resource_unit_code=#{code}") ResourceUnit selectUnitByCode(String code);
 @Select("SELECT * FROM resource_unit WHERE id=#{id}") ResourceUnit selectUnitById(Long id);
 @Select("SELECT rus.* FROM resource_unit_step rus JOIN resource_unit ru ON ru.id=rus.resource_unit_id WHERE ru.path_version_id=#{versionId} ORDER BY rus.order_no") List<ResourceUnitStep> selectConsumedSteps(Long versionId);
 @Select("SELECT * FROM resource_unit_step WHERE resource_unit_id=#{unitId} ORDER BY order_no") List<ResourceUnitStep> selectUnitSteps(Long unitId);
 @Insert({"<script>","INSERT INTO resource_unit_step(resource_unit_id,path_step_id,order_no) VALUES","<foreach collection='rows' item='r' separator=','>","(#{r.resourceUnitId},#{r.pathStepId},#{r.orderNo})","</foreach>","</script>"}) int batchInsertUnitSteps(@Param("rows")List<ResourceUnitStep> rows);
 @Insert("INSERT INTO resource_blueprint(blueprint_code,resource_unit_id,profile_version_used,policy_version,status,resource_plan_json,learning_question_plan_json,hidden_assessment_plan_json,profile_evidence_json,graph_evidence_json,capability_snapshot_json,schema_version,correlation_id,created_at) VALUES(#{blueprintCode},#{resourceUnitId},#{profileVersionUsed},#{policyVersion},#{status},#{resourcePlanJson},#{learningQuestionPlanJson},#{hiddenAssessmentPlanJson},#{profileEvidenceJson},#{graphEvidenceJson},#{capabilitySnapshotJson},#{schemaVersion},#{correlationId},NOW(3))") @Options(useGeneratedKeys=true,keyProperty="id") int insertBlueprint(ResourceBlueprint v);
 @Select("SELECT * FROM resource_blueprint WHERE id=#{id}") ResourceBlueprint selectBlueprint(Long id);
 @Insert("INSERT INTO resource_generation_job(job_code,user_id,course_id,path_version_id,resource_unit_id,blueprint_id,generation_policy_version,idempotency_key,status,retry_count,max_revision_rounds,input_snapshot_json,correlation_id,created_at) VALUES(#{jobCode},#{userId},#{courseId},#{pathVersionId},#{resourceUnitId},#{blueprintId},#{generationPolicyVersion},#{idempotencyKey},#{status},0,#{maxRevisionRounds},#{inputSnapshotJson},#{correlationId},NOW(3))") @Options(useGeneratedKeys=true,keyProperty="id") int insertJob(ResourceGenerationJob v);
 @Select("SELECT * FROM resource_generation_job WHERE user_id=#{userId} AND idempotency_key=#{key} LIMIT 1") ResourceGenerationJob selectJobByIdempotency(@Param("userId")Long userId,@Param("key")String key);
 @Select("SELECT * FROM resource_generation_job WHERE job_code=#{code} LIMIT 1") ResourceGenerationJob selectJobByCode(String code);
 @Update("UPDATE resource_generation_job SET resource_unit_id=#{resourceUnitId},blueprint_id=#{blueprintId},status=#{status},error_code=#{errorCode},error_message=#{errorMessage},started_at=COALESCE(started_at,NOW(3)),finished_at=CASE WHEN #{status} IN('PUBLISHED','FAILED','CANCELED') THEN NOW(3) ELSE finished_at END WHERE id=#{id}") int updateJob(ResourceGenerationJob v);
 @Insert("INSERT INTO resource_bundle(bundle_code,user_id,course_id,resource_unit_id,blueprint_id,version,status,profile_version_used,graph_version,policy_version,content_hash,stale_reason,correlation_id,created_at) VALUES(#{bundleCode},#{userId},#{courseId},#{resourceUnitId},#{blueprintId},#{version},#{status},#{profileVersionUsed},#{graphVersion},#{policyVersion},#{contentHash},#{staleReason},#{correlationId},NOW(3))") @Options(useGeneratedKeys=true,keyProperty="id") int insertBundle(ResourceBundle v);
 @Select("SELECT * FROM resource_bundle WHERE bundle_code=#{code} LIMIT 1") ResourceBundle selectBundleByCode(String code);
 @Select("SELECT * FROM resource_bundle WHERE id=#{id} LIMIT 1 FOR UPDATE") ResourceBundle selectBundleByIdForUpdate(Long id);
 @Select("SELECT * FROM resource_bundle WHERE resource_unit_id=#{unitId} ORDER BY version DESC,id DESC LIMIT 1") ResourceBundle selectLatestBundle(Long unitId);
 @Update("UPDATE resource_bundle SET status='PUBLISHED',content_hash=#{contentHash},published_at=NOW(3) WHERE id=#{id} AND status='IN_REVIEW'") int publishBundle(@Param("id")Long id,@Param("contentHash")String contentHash);
 @Update("UPDATE resource_bundle SET status=#{status},stale_reason=#{reason} WHERE id=#{id}") int updateBundleStatus(@Param("id")Long id,@Param("status")String status,@Param("reason")String reason);
 @Insert({"<script>","INSERT INTO resource_item(bundle_id,item_code,generated_question_code,item_type,purpose,visibility,title,content_json,question_difficulty,cognitive_level,grading_key_json,order_no,status,normalized_text_hash,simhash64,created_at) VALUES","<foreach collection='rows' item='r' separator=','>","(#{r.bundleId},#{r.itemCode},#{r.generatedQuestionCode},#{r.itemType},#{r.purpose},#{r.visibility},#{r.title},#{r.contentJson},#{r.questionDifficulty},#{r.cognitiveLevel},#{r.gradingKeyJson},#{r.orderNo},#{r.status},#{r.normalizedTextHash},#{r.simhash64},NOW(3))","</foreach>","</script>"}) int batchInsertItems(@Param("rows")List<ResourceItem> rows);
 @Select("SELECT id,bundle_id,item_code,generated_question_code,item_type,purpose,visibility,title,content_json,question_difficulty,cognitive_level,order_no,status,created_at FROM resource_item WHERE bundle_id=#{bundleId} AND visibility='VISIBLE' AND status='ACTIVE' ORDER BY order_no,id") List<ResourceItem> selectVisibleItems(Long bundleId);
 @Select("SELECT * FROM resource_item WHERE bundle_id=#{bundleId} ORDER BY order_no,id") List<ResourceItem> selectAllItems(Long bundleId);
 @Select("SELECT * FROM resource_item WHERE generated_question_code=#{code} LIMIT 1 FOR UPDATE") ResourceItem selectQuestionForUpdate(String code);
 @Select("SELECT * FROM resource_item WHERE generated_question_code IS NOT NULL AND bundle_id<>#{bundleId} ORDER BY id DESC LIMIT #{limit}") List<ResourceItem> recentQuestions(@Param("bundleId")Long bundleId,@Param("limit")int limit);
 @Insert("INSERT INTO resource_review(job_id,bundle_id,blueprint_id,expert_role,result,issue_type,location,description,repair_target,repair_scope,repair_action,repair_instruction,critical,round_no,report_json,created_at) VALUES(#{jobId},#{bundleId},#{blueprintId},#{expertRole},#{result},#{issueType},#{location},#{description},#{repairTarget},#{repairScope},#{repairAction},#{repairInstruction},#{critical},#{roundNo},#{reportJson},NOW(3))") @Options(useGeneratedKeys=true,keyProperty="id") int insertReview(ResourceReview v);
 @Select("SELECT * FROM resource_review WHERE job_id=#{jobId} ORDER BY round_no,expert_role,id") List<ResourceReview> selectReviews(Long jobId);
 @Select("SELECT resource_type FROM course_resource_capability WHERE course_id=#{courseId} AND enabled=1 ORDER BY resource_type") List<String> capabilities(Long courseId);
 @Insert("INSERT INTO resource_knowledge(resource_item_id,knowledge_point_id,relation_type,coverage_weight,is_primary,created_at) VALUES(#{itemId},#{knowledgePointId},#{relationType},#{weight},#{primary},NOW(3))") int insertItemKnowledge(@Param("itemId")Long itemId,@Param("knowledgePointId")Long knowledgePointId,@Param("relationType")String relationType,@Param("weight")java.math.BigDecimal weight,@Param("primary")int primary);
 @Select("SELECT knowledge_point_id,coverage_weight,is_primary FROM resource_knowledge WHERE resource_item_id=#{itemId}") List<Map<String,Object>> itemKnowledge(Long itemId);
 @Insert("INSERT INTO resource_assessment_release(release_code,user_id,bundle_id,resource_item_id,status,released_at,expires_at,created_at) VALUES(#{releaseCode},#{userId},#{bundleId},#{resourceItemId},#{status},#{releasedAt},#{expiresAt},NOW(3))") @Options(useGeneratedKeys=true,keyProperty="id") int insertRelease(ResourceAssessmentRelease v);
 @Select("SELECT * FROM resource_assessment_release WHERE user_id=#{userId} AND resource_item_id=#{itemId} AND status='ACTIVE' AND (expires_at IS NULL OR expires_at>NOW(3)) ORDER BY id DESC LIMIT 1 FOR UPDATE") ResourceAssessmentRelease selectActiveRelease(@Param("userId")Long userId,@Param("itemId")Long itemId);
 @Select("SELECT ri.id,ri.bundle_id,ri.item_code,ri.generated_question_code,ri.item_type,ri.purpose,ri.visibility,ri.title,ri.content_json,ri.question_difficulty,ri.cognitive_level,ri.order_no,ri.status FROM resource_item ri JOIN resource_assessment_release ar ON ar.resource_item_id=ri.id WHERE ar.user_id=#{userId} AND ar.bundle_id=#{bundleId} AND ar.status='ACTIVE' AND (ar.expires_at IS NULL OR ar.expires_at>NOW(3)) ORDER BY ri.order_no") List<ResourceItem> activeAssessments(@Param("userId")Long userId,@Param("bundleId")Long bundleId);
 @Update("UPDATE resource_assessment_release SET status='CONSUMED',consumed_at=NOW(3) WHERE id=#{id} AND status='ACTIVE'") int consumeRelease(Long id);
 @Select("SELECT * FROM resource_interaction WHERE request_id=#{requestId} LIMIT 1") ResourceInteraction selectInteractionByRequest(String requestId);
 @Select("SELECT * FROM resource_interaction WHERE interaction_code=#{code} AND user_id=#{userId}") ResourceInteraction selectInteraction(@Param("code")String code,@Param("userId")Long userId);
 @Insert("INSERT INTO resource_interaction(interaction_code,interaction_seq,user_id,course_id,resource_bundle_id,resource_version,resource_unit_id,resource_item_id,generated_question_code,question_purpose,visibility,question_difficulty,primary_knowledge_point_id,knowledge_point_weights_json,score_normalized,correct,status,action_origin,grading_version,answer_json,request_id,correlation_id,client_occurred_at,submitted_at,created_at) VALUES(#{interactionCode},#{interactionSeq},#{userId},#{courseId},#{resourceBundleId},#{resourceVersion},#{resourceUnitId},#{resourceItemId},#{generatedQuestionCode},#{questionPurpose},#{visibility},#{questionDifficulty},#{primaryKnowledgePointId},#{knowledgePointWeightsJson},#{scoreNormalized},#{correct},#{status},#{actionOrigin},#{gradingVersion},#{answerJson},#{requestId},#{correlationId},#{clientOccurredAt},NOW(3),NOW(3))") @Options(useGeneratedKeys=true,keyProperty="id") int insertInteraction(ResourceInteraction v);
 @Insert("INSERT INTO outbox_event(event_id,aggregate_type,aggregate_id,event_type,payload_json,status,retry_count,next_retry_at,correlation_id,created_at) VALUES(#{eventId},#{aggregateType},#{aggregateId},#{eventType},#{payloadJson},#{status},0,#{nextRetryAt},#{correlationId},NOW(3))") @Options(useGeneratedKeys=true,keyProperty="id") int insertOutbox(OutboxEvent v);
 @Insert("INSERT INTO profile_evidence_event(event_id,interaction_id,consumer_name,status,retry_count,processed_at,error_message) VALUES(#{eventId},#{interactionId},#{consumerName},#{status},0,#{processedAt},#{errorMessage})") @Options(useGeneratedKeys=true,keyProperty="id") int insertEvidenceEvent(ProfileEvidenceEvent v);
 @Update("UPDATE profile_evidence_event SET status='PROCESSED',processed_at=NOW(3) WHERE event_id=#{eventId} AND consumer_name=#{consumer}") int markEvidenceProcessed(@Param("eventId")String eventId,@Param("consumer")String consumer);
 @Insert("INSERT INTO resource_action_decision(user_id,course_id,path_id,path_version,interaction_id,action,reason,correlation_id,created_at) VALUES(#{userId},#{courseId},#{pathId},#{pathVersion},#{interactionId},#{action},#{reason},#{correlationId},NOW(3))") int insertResourceDecision(@Param("userId")Long userId,@Param("courseId")Long courseId,@Param("pathId")Long pathId,@Param("pathVersion")Long pathVersion,@Param("interactionId")Long interactionId,@Param("action")String action,@Param("reason")String reason,@Param("correlationId")String correlationId);
 @Select("SELECT * FROM outbox_event WHERE status='PENDING' AND (next_retry_at IS NULL OR next_retry_at<=NOW(3)) ORDER BY id LIMIT #{limit}") List<OutboxEvent> pendingOutbox(@Param("limit")int limit);
 @Update("UPDATE outbox_event SET status='PUBLISHED',published_at=NOW(3) WHERE id=#{id} AND status='PENDING'") int markOutboxPublished(Long id);
}
